import { StyleSheet, View, Text, FlatList, ActivityIndicator, TouchableOpacity } from 'react-native';
import { useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { getScanHistory } from '../../utils/storage';

interface ScanRecord {
  id: string;
  timestamp: number;
  category: string;
  label: string;
  confidence: number;
  severity: string;
}

export default function HistoryScreen() {
  const { t } = useTranslation();
  const [history, setHistory] = useState<ScanRecord[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadHistory();
  }, []);

  const loadHistory = async () => {
    try {
      const records = await getScanHistory();
      setHistory(records);
    } catch (error) {
      console.error('Error loading history:', error);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <View style={styles.container}>
        <ActivityIndicator size="large" color="#0066cc" />
      </View>
    );
  }

  if (history.length === 0) {
    return (
      <View style={styles.emptyContainer}>
        <Text style={styles.emptyIcon}>📋</Text>
        <Text style={styles.emptyTitle}>{t('history.noScans')}</Text>
        <Text style={styles.emptyDescription}>{t('history.noScansDescription')}</Text>
      </View>
    );
  }

  return (
    <View style={styles.container}>
      <FlatList
        data={history}
        keyExtractor={(item) => item.id}
        renderItem={({ item }) => <ScanHistoryItem record={item} />}
        contentContainerStyle={styles.listContent}
      />
    </View>
  );
}

function ScanHistoryItem({ record }: { record: ScanRecord }) {
  const { t } = useTranslation();
  const date = new Date(record.timestamp);
  const dateStr = date.toLocaleDateString();
  const timeStr = date.toLocaleTimeString();

  const severityColor = {
    low: '#4caf50',
    moderate: '#ff9800',
    high: '#f44336',
  }[record.severity] || '#999';

  return (
    <TouchableOpacity style={styles.historyCard}>
      <View style={styles.cardHeader}>
        <Text style={styles.label}>{record.label}</Text>
        <View style={[styles.severityBadge, { backgroundColor: severityColor }]}>
          <Text style={styles.severityText}>{record.severity}</Text>
        </View>
      </View>
      <View style={styles.cardBody}>
        <View style={styles.infoRow}>
          <Text style={styles.infoLabel}>{t('history.category')}:</Text>
          <Text style={styles.infoValue}>{record.category}</Text>
        </View>
        <View style={styles.infoRow}>
          <Text style={styles.infoLabel}>{t('history.confidence')}:</Text>
          <Text style={styles.infoValue}>{(record.confidence * 100).toFixed(1)}%</Text>
        </View>
        <View style={styles.infoRow}>
          <Text style={styles.infoLabel}>{t('history.date')}:</Text>
          <Text style={styles.infoValue}>{dateStr} {timeStr}</Text>
        </View>
      </View>
    </TouchableOpacity>
  );
}

