import { StyleSheet, View, Text, TouchableOpacity, ActivityIndicator, Alert } from 'react-native';
import { Camera, CameraType } from 'expo-camera';
import { useRef, useState } from 'react';
import { useTranslation } from 'react-i18next';
import CameraCapture from '../../components/CameraCapture';

export default function ScanScreen() {
  const { t } = useTranslation();
  const [scanning, setScanning] = useState(false);
  const [cameraPermission, setCameraPermission] = useState<boolean | null>(null);
  const cameraRef = useRef<Camera>(null);

  const requestCameraPermission = async () => {
    const { status } = await Camera.requestCameraPermissionsAsync();
    setCameraPermission(status === 'granted');
  };

  const handleCapture = async (imageUri: string) => {
    setScanning(true);
    try {
      // TODO: Implement ONNX inference here
      // For now, show a placeholder
      Alert.alert(
        t('scan.processing'),
        t('scan.processingDescription'),
        [{ text: t('common.ok') }]
      );
    } catch (error) {
      Alert.alert(t('common.error'), t('scan.error'));
      console.error('Scanning error:', error);
    } finally {
      setScanning(false);
    }
  };

  if (cameraPermission === null) {
    return (
      <View style={styles.container}>
        <Text style={styles.message}>{t('scan.requestPermission')}</Text>
        <TouchableOpacity style={styles.button} onPress={requestCameraPermission}>
          <Text style={styles.buttonText}>{t('common.allow')}</Text>
        </TouchableOpacity>
      </View>
    );
  }

  if (cameraPermission === false) {
    return (
      <View style={styles.container}>
        <Text style={styles.message}>{t('scan.cameraNotAllowed')}</Text>
      </View>
    );
  }

  return (
    <View style={styles.container}>
      <CameraCapture onCapture={handleCapture} />
      {scanning && (
        <View style={styles.loadingOverlay}>
          <ActivityIndicator size="large" color="#fff" />
          <Text style={styles.loadingText}>{t('scan.analyzing')}</Text>
        </View>
      )}
    </View>
  );
}

