import { StyleSheet, View, Text, ScrollView, TouchableOpacity } from 'react-native';
import { useTranslation } from 'react-i18next';

interface ScanResult {
  label: string;
  confidence: number;
  severity: 'low' | 'moderate' | 'high';
  recommendation: string;
  description: string;
}

interface ResultCardProps {
  result: ScanResult;
  onSave?: () => void;
  onRetry?: () => void;
}

export default function ResultCard({ result, onSave, onRetry }: ResultCardProps) {
  const { t } = useTranslation();

  const severityColor = {
    low: '#4caf50',
    moderate: '#ff9800',
    high: '#f44336',
  };

  const severityBg = {
    low: '#e8f5e9',
    moderate: '#fff3e0',
    high: '#ffebee',
  };

  const getSeverityIcon = (severity: string) => {
    switch (severity) {
      case 'low':
        return '✅';
      case 'moderate':
        return '⚠️';
      case 'high':
        return '⛔';
      default:
        return '❓';
    }
  };

  return (
    <ScrollView style={styles.container}>
      <View style={styles.content}>
        {/* Disclaimer */}
        <View style={styles.disclaimerBar}>
          <Text style={styles.disclaimerText}>
            💡 {t('result.disclaimer')}
          </Text>
        </View>

        {/* Result Header */}
        <View
          style={[
            styles.resultHeader,
            { backgroundColor: severityBg[result.severity] },
          ]}
        >
          <Text style={styles.severityIcon}>
            {getSeverityIcon(result.severity)}
          </Text>
          <Text style={styles.resultLabel}>{result.label}</Text>
          <View
            style={[
              styles.severityBadge,
              { backgroundColor: severityColor[result.severity] },
            ]}
          >
            <Text style={styles.severityText}>{result.severity}</Text>
          </View>
        </View>

        {/* Confidence Score */}
        <View style={styles.card}>
          <Text style={styles.cardTitle}>{t('result.confidence')}</Text>
          <View style={styles.confidenceContainer}>
            <View style={styles.progressBar}>
              <View
                style={[
                  styles.progressFill,
                  {
                    width: `${result.confidence * 100}%`,
                    backgroundColor: severityColor[result.severity],
                  },
                ]}
              />
            </View>
            <Text style={styles.confidenceValue}>
              {(result.confidence * 100).toFixed(1)}%
            </Text>
          </View>
        </View>

        {/* Recommendation */}
        <View style={styles.card}>
          <Text style={styles.cardTitle}>{t('result.recommendation')}</Text>
          <View style={styles.recommendationBox}>
            <Text style={styles.recommendationText}>{result.recommendation}</Text>
          </View>
        </View>

        {/* Description */}
        <View style={styles.card}>
          <Text style={styles.cardTitle}>{t('result.explanation')}</Text>
          <Text style={styles.descriptionText}>{result.description}</Text>
        </View>

        {/* Actions */}
        <View style={styles.actions}>
          {onRetry && (
            <TouchableOpacity style={styles.secondaryButton} onPress={onRetry}>
              <Text style={styles.secondaryButtonText}>🔄 {t('result.retake')}</Text>
            </TouchableOpacity>
          )}
          {onSave && (
            <TouchableOpacity style={styles.primaryButton} onPress={onSave}>
              <Text style={styles.primaryButtonText}>💾 {t('result.save')}</Text>
            </TouchableOpacity>
          )}
        </View>

        {/* Footer */}
        <View style={styles.footer}>
          <Text style={styles.footerText}>{t('result.notDiagnosis')}</Text>
        </View>
      </View>
    </ScrollView>
  );
}

