import * as SQLite from 'expo-sqlite';
import { v4 as uuidv4 } from 'uuid';

const db = SQLite.openDatabase('mediscan.db');

export interface ScanRecord {
  id: string;
  timestamp: number;
  category: string;
  label: string;
  confidence: number;
  severity: string;
  recommendation: string;
  imageUri?: string;
  patientId?: string;
}

// Initialize database schema
export async function initializeDatabase() {
  return new Promise<void>((resolve, reject) => {
    db.transaction((tx) => {
      tx.executeSql(
        `
        CREATE TABLE IF NOT EXISTS scans (
          id TEXT PRIMARY KEY,
          timestamp INTEGER NOT NULL,
          category TEXT NOT NULL,
          label TEXT NOT NULL,
          confidence REAL NOT NULL,
          severity TEXT NOT NULL,
          recommendation TEXT NOT NULL,
          imageUri TEXT,
          patientId TEXT,
          createdAt DATETIME DEFAULT CURRENT_TIMESTAMP
        );
        `,
        [],
        () => {
          console.log('Database initialized successfully');
          resolve();
        },
        (_, error) => {
          console.error('Database initialization error:', error);
          reject(error);
          return false;
        }
      );
    });
  });
}

// Save a scan result
export async function saveScan(scan: Omit<ScanRecord, 'id'>): Promise<string> {
  return new Promise((resolve, reject) => {
    const id = uuidv4();
    db.transaction((tx) => {
      tx.executeSql(
        `
        INSERT INTO scans (id, timestamp, category, label, confidence, severity, recommendation, imageUri, patientId)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?);
        `,
        [
          id,
          scan.timestamp,
          scan.category,
          scan.label,
          scan.confidence,
          scan.severity,
          scan.recommendation,
          scan.imageUri || null,
          scan.patientId || null,
        ],
        () => {
          console.log('Scan saved successfully with id:', id);
          resolve(id);
        },
        (_, error) => {
          console.error('Error saving scan:', error);
          reject(error);
          return false;
        }
      );
    });
  });
}

// Get all scans
export async function getScanHistory(): Promise<ScanRecord[]> {
  return new Promise((resolve, reject) => {
    db.transaction((tx) => {
      tx.executeSql(
        `SELECT * FROM scans ORDER BY timestamp DESC;`,
        [],
        (_, result) => {
          const scans = result.rows._array as ScanRecord[];
          console.log('Retrieved scans:', scans.length);
          resolve(scans);
        },
        (_, error) => {
          console.error('Error retrieving scans:', error);
          reject(error);
          return false;
        }
      );
    });
  });
}

// Get scan by ID
export async function getScan(id: string): Promise<ScanRecord | null> {
  return new Promise((resolve, reject) => {
    db.transaction((tx) => {
      tx.executeSql(
        `SELECT * FROM scans WHERE id = ?;`,
        [id],
        (_, result) => {
          const scan = result.rows._array[0] as ScanRecord | undefined;
          resolve(scan || null);
        },
        (_, error) => {
          console.error('Error retrieving scan:', error);
          reject(error);
          return false;
        }
      );
    });
  });
}

// Get scans by category
export async function getScansByCategory(category: string): Promise<ScanRecord[]> {
  return new Promise((resolve, reject) => {
    db.transaction((tx) => {
      tx.executeSql(
        `SELECT * FROM scans WHERE category = ? ORDER BY timestamp DESC;`,
        [category],
        (_, result) => {
          const scans = result.rows._array as ScanRecord[];
          resolve(scans);
        },
        (_, error) => {
          console.error('Error retrieving scans by category:', error);
          reject(error);
          return false;
        }
      );
    });
  });
}

// Delete a scan
export async function deleteScan(id: string): Promise<void> {
  return new Promise((resolve, reject) => {
    db.transaction((tx) => {
      tx.executeSql(
        `DELETE FROM scans WHERE id = ?;`,
        [id],
        () => {
          console.log('Scan deleted successfully');
          resolve();
        },
        (_, error) => {
          console.error('Error deleting scan:', error);
          reject(error);
          return false;
        }
      );
    });
  });
}

// Clear all scans
export async function clearAllScans(): Promise<void> {
  return new Promise((resolve, reject) => {
    db.transaction((tx) => {
      tx.executeSql(
        `DELETE FROM scans;`,
        [],
        () => {
          console.log('All scans cleared');
          resolve();
        },
        (_, error) => {
          console.error('Error clearing scans:', error);
          reject(error);
          return false;
        }
      );
    });
  });
}

// Get statistics
export async function getScanStatistics() {
  return new Promise((resolve, reject) => {
    db.transaction((tx) => {
      tx.executeSql(
        `
        SELECT 
          COUNT(*) as totalScans,
          category,
          AVG(confidence) as avgConfidence
        FROM scans
        GROUP BY category;
        `,
        [],
        (_, result) => {
          const stats = result.rows._array;
          resolve(stats);
        },
        (_, error) => {
          console.error('Error retrieving statistics:', error);
          reject(error);
          return false;
        }
      );
    });
  });
}
